        auto=Switch(this).apply{typeface=font;text="Auto";setTextColor(Color.WHITE);contentDescription="Automatic capture";isChecked=false
            setOnCheckedChangeListener{_,checked->autoMode=checked;stability.reset();status.text=if(checked)"Auto preview: hold the page steady; check each crop." else "Manual capture. Adjust corners in review."}}
        controls.addView(auto,LinearLayout.LayoutParams(0,dp(52),1f))
        shutter=button("Capture"){takePhoto(false)};shutter.isEnabled=false;controls.addView(shutter,LinearLayout.LayoutParams(0,dp(52),1f))
        root.addView(controls)
        zoom=SeekBar(this).apply{max=100;contentDescription="Camera zoom";isEnabled=false
            setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{
                override fun onProgressChanged(bar:SeekBar?,value:Int,fromUser:Boolean){if(fromUser&&!busy){camera?.cameraControl?.setLinearZoom(value/100f);stability.reset();latest=null}}
                override fun onStartTrackingTouch(bar:SeekBar?){};override fun onStopTrackingTouch(bar:SeekBar?){}
            })}
        root.addView(zoom,LinearLayout.LayoutParams(-1,dp(36)))
        strip=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL}
        val scroll=HorizontalScrollView(this).apply{addView(strip);isHorizontalScrollBarEnabled=false}
        root.addView(scroll,LinearLayout.LayoutParams(-1,dp(72)))
        val fallback=LinearLayout(this)
        fallback.addView(button("Gallery"){finishReview("gallery")},LinearLayout.LayoutParams(0,dp(48),1f))
        fallback.addView(button("Other scanner"){finishReview("legacy")},LinearLayout.LayoutParams(0,dp(48),1f));root.addView(fallback)
        setContentView(root);root.requestApplyInsets()
        onBackPressedDispatcher.addCallback(this,object:OnBackPressedCallback(true){override fun handleOnBackPressed(){finishReview()}})
        preview.addOnLayoutChangeListener{_,l,t,r,b,ol,ot,orr,ob->if(r-l!=orr-ol||b-t!=ob-ot){if(!busy&&running)preview.post{bindCamera()}}}
        ScanWork.executor.execute{
            try{val recovered=store.recover();runOnUiThread{pages=recovered;busy=false;updatePages();requestCamera()}}
            catch(_:Exception){runOnUiThread{busy=false;status.text="Could not recover the pending page. Earlier pages are safe.";retry.visibility=View.VISIBLE;retry.text=if(shouldShowRequestPermissionRationale(Manifest.permission.CAMERA))"Allow camera" else "Open app settings"}}
        }
    }
    private fun requestCamera(){
        if(checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED){retry.visibility=View.GONE;preview.post{bindCamera()}}
        else if(retry.text.toString()=="Open app settings"){startActivity(Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:$packageName")))}
        else{status.text="Camera access is needed to scan. Gallery and the other scanner are available.";retry.visibility=View.VISIBLE
            requestPermissions(arrayOf(Manifest.permission.CAMERA),701)}
    }
    override fun onRequestPermissionsResult(requestCode:Int,permissions:Array<out String>,results:IntArray){
        super.onRequestPermissionsResult(requestCode,permissions,results)
        if(requestCode==701){if(results.firstOrNull()==PackageManager.PERMISSION_GRANTED){retry.visibility=View.GONE;preview.post{bindCamera()}}
            else{status.text="Camera access was denied. Allow it in app settings, or choose Gallery / Other scanner.";retry.visibility=View.VISIBLE;retry.text=if(shouldShowRequestPermissionRationale(Manifest.permission.CAMERA))"Allow camera" else "Open app settings"}}
    }
    private fun bindCamera(){
        if(isFinishing||isDestroyed||busy||checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED||preview.width==0||preview.height==0)return
        val rotation=preview.display?.rotation?:Surface.ROTATION_0
        if(running&&boundRotation==rotation&&boundWidth==preview.width&&boundHeight==preview.height&&camera!=null)return
        val token=++session
        val future=ProcessCameraProvider.getInstance(this)
        future.addListener({
            if(isFinishing||isDestroyed||token!=session)return@addListener
            try{
                val p=future.get();provider=p;p.unbindAll()
                val live=Preview.Builder().setTargetAspectRatio(AspectRatio.RATIO_4_3).setTargetRotation(rotation).build()
                val still=ImageCapture.Builder().setCaptureMode(ImageCapture.CAPTURE_MODE_MINIMIZE_LATENCY).setTargetAspectRatio(AspectRatio.RATIO_4_3).setTargetRotation(rotation).build()
                val frames=ImageAnalysis.Builder().setTargetResolution(android.util.Size(640,480)).setTargetRotation(rotation).setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).build()
                live.setSurfaceProvider(preview.surfaceProvider)
                val group=UseCaseGroup.Builder().addUseCase(live).addUseCase(still).addUseCase(frames)
                preview.viewPort?.let{group.setViewPort(it)}?:throw IllegalStateException("Preview not ready")
                camera=p.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,group.build())
                capture=still;analysis=frames;boundRotation=rotation;boundWidth=preview.width;boundHeight=preview.height;running=true;latest=null;stability.reset()
                frames.setAnalyzer(analyzer){image->analyze(image,token)}
                torchOn=false;torch.text="Torch off";torch.isEnabled=camera?.cameraInfo?.hasFlashUnit()==true
                zoom.progress=0;zoom.isEnabled=true;retry.visibility=View.GONE
                status.text="Keep the whole page in view. Tap Capture anytime.";updateControls()
            }catch(_:Exception){running=false;capture=null;shutter.isEnabled=false;torch.isEnabled=false;zoom.isEnabled=false;status.text="Live camera unavailable on this device. Use Gallery or Other scanner."}
        },ContextCompat.getMainExecutor(this))
    }
    private fun analyze(image:ImageProxy,token:Int){
        try{
            val now=SystemClock.elapsedRealtime();if(now-lastAnalysis<200)return;lastAnalysis=now
            val rect=image.cropRect;val plane=image.planes[0]
            val gray=ScanDetector.sample(plane.buffer,plane.rowStride,plane.pixelStride,rect.left,rect.top,rect.width(),rect.height(),image.imageInfo.rotationDegrees)
            val candidate=ScanDetector.detect(gray)
            runOnUiThread{
                if(!running||!resumed||busy||isFinishing||isDestroyed||token!=session)return@runOnUiThread
                val result=stability.update(candidate,now);latest=result.candidate;latestAt=now
                overlay.update(result.candidate?.corners,result.stable)
                status.text=when{pages.size>=30->"30 pages ready. Review and save before adding more."
                    result.candidate==null->"No clear page outline. Manual Capture is available."
                    autoMode&&result.ready->"Page steady — capturing…"
                    autoMode&&result.stable->"Lift the page out of view before the next auto capture."
                    autoMode->"Hold steady. Improve light or use manual Capture."
                    else->"Page outline found. Tap Capture or turn on Auto."}
                if(autoMode&&result.ready&&pages.size<30)takePhoto(true)
            }
        }catch(_:Exception){/* An uncertain/malformed frame never disables manual capture. */}
        finally{image.close()}
    }
    private fun takePhoto(automatic:Boolean){
        val still=capture?:return;if(busy||!running||!resumed||pages.size>=30)return
        busy=true;updateControls();status.text="Saving original page…"
        val proposed=if(automatic&&SystemClock.elapsedRealtime()-latestAt<400)latest else null
        stability.captured();overlay.update(null,false)
        val app=applicationContext
        ScanWork.executor.execute{
            try{
                require(store.folder.usableSpace>64L*1024*1024){"Free storage before capturing."}
                val output=store.newCapture()
                runOnUiThread{
                    if(isFinishing||isDestroyed){ScanWork.executor.execute{store.finishCapture(false)};return@runOnUiThread}
                    still.takePicture(ImageCapture.OutputFileOptions.Builder(output).build(),ContextCompat.getMainExecutor(this),object:ImageCapture.OnImageSavedCallback{
                        override fun onImageSaved(result:ImageCapture.OutputFileResults){
                            ScanWork.executor.execute{
                                var saved=emptyList<String>();var warning=false
                                try{
                                    saved=ScanDraftStore(app).finishCapture(true)
                                    if(proposed!=null){
                                        val bounds=StudioImages.load(saved.last(),160)
                                        val ratio=bounds.width.toDouble()/bounds.height;bounds.recycle()
                                        // ViewPort aligns streams; refuse a stale/aspect-mismatched crop rather than cut content.
                                        if(abs(ratio/proposed.ratio-1)<.035){
                                            try{saved=ScanDraftStore(app).edit(listOf(saved.last()),"original",null,proposed.corners)}catch(_:Exception){warning=true}
                                        }else warning=true
                                    }
                                    val completed=saved
                                    runOnUiThread{if(!isDestroyed){pages=completed;busy=false;updatePages();status.text=if(warning)"Photo saved. Check and adjust its corners in review." else "Page saved. Lift it away before the next auto capture."}}
                                }catch(_:Exception){runOnUiThread{if(!isDestroyed){busy=false;status.text="Could not finish this page. Earlier pages are safe; retry or review.";updateControls()}}}
                            }
                        }
                        override fun onError(error:ImageCaptureException){ScanWork.executor.execute{try{store.finishCapture(false)}catch(_:Exception){};runOnUiThread{if(!isDestroyed){busy=false;status.text="Capture failed. Earlier pages are safe.";updateControls()}}}}
                    })
                }
            }catch(_:Exception){runOnUiThread{if(!isDestroyed){busy=false;status.text="Could not start this page. Review your saved pages or free storage.";updateControls()}}}
        }
    }
    private fun updateControls(){shutter.isEnabled=running&&!busy&&pages.size<30;done.isEnabled=!busy;auto.isEnabled=!busy;torch.isEnabled=!busy&&camera?.cameraInfo?.hasFlashUnit()==true;zoom.isEnabled=running&&!busy}
    private fun updatePages(){
        done.text="Review (${pages.size})";updateControls();if(boundRotation<0&&running)preview.post{bindCamera()};strip.removeAllViews()
        // Only bounded thumbnails are decoded, serially; stale callbacks cannot attach to a new strip.
        val current=pages.toList();val generation=++thumbnailGeneration
        current.forEachIndexed{index,path->
            val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;contentDescription="Page ${index+1}. Review saved pages.";setOnClickListener{finishReview()}}
            val image=ImageView(this).apply{scaleType=ImageView.ScaleType.FIT_CENTER};box.addView(image,LinearLayout.LayoutParams(dp(48),dp(44)))
            box.addView(label("${index+1}").apply{textSize=11f;setPadding(0,0,0,0)})
            strip.addView(box,LinearLayout.LayoutParams(dp(60),dp(68)))
            ScanWork.executor.execute{try{val bitmap=StudioImages.load(path,128);runOnUiThread{if(isDestroyed||generation!=thumbnailGeneration)bitmap.recycle()else image.setImageBitmap(bitmap)}}catch(_:Exception){}}
        }
    }
    private var thumbnailGeneration=0
    private fun toggleTorch(){if(busy)return;val c=camera?:return;if(!c.cameraInfo.hasFlashUnit())return
        val next=!torchOn;val task=c.cameraControl.enableTorch(next)
        task.addListener({try{task.get();torchOn=next;torch.text=if(next)"Torch on" else "Torch off";stability.reset()}catch(_:Exception){status.text="Torch could not be changed on this device."}},ContextCompat.getMainExecutor(this))}
    private fun finishReview(action:String="review"){if(busy){status.text="Finishing this page. Please wait.";return};setResult(RESULT_OK,Intent().putExtra("action",action));finish()}
    override fun onConfigurationChanged(newConfig:Configuration){super.onConfigurationChanged(newConfig);boundRotation=-1;stability.reset();latest=null;preview.post{bindCamera()}}
    override fun onResume(){super.onResume();resumed=true;if(!busy&&checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)preview.post{bindCamera()}}
    override fun onPause(){resumed=false;super.onPause();latest=null;stability.reset();overlay.update(null,false);camera?.cameraControl?.enableTorch(false);torchOn=false;torch.text="Torch off"}
    override fun onDestroy(){session++;thumbnailGeneration++;running=false;analysis?.clearAnalyzer();provider?.unbindAll();analyzer.shutdown();super.onDestroy()}
}

class ScanOutline(context:android.content.Context):View(context){
    private var corners:List<Double>?=null;private var stable=false
    fun update(points:List<Double>?,steady:Boolean){corners=points;stable=steady;invalidate()}
    override fun onDraw(canvas:Canvas){super.onDraw(canvas);val q=corners?:return
        val path=Path().apply{moveTo((q[0]*width).toFloat(),(q[1]*height).toFloat());for(i in 1..3)lineTo((q[i*2]*width).toFloat(),(q[i*2+1]*height).toFloat());close()}
        val color=if(stable)Color.rgb(89,231,184)else Color.rgb(255,218,115)
        canvas.drawPath(path,Paint(Paint.ANTI_ALIAS_FLAG).apply{this.color=color;style=Paint.Style.STROKE;strokeWidth=3*resources.displayMetrics.density})
        for(i in 0..3)canvas.drawCircle((q[i*2]*width).toFloat(),(q[i*2+1]*height).toFloat(),5*resources.displayMetrics.density,Paint(Paint.ANTI_ALIAS_FLAG).apply{this.color=color})
    }
}

package com.hyzen.pharmd

import android.app.Activity
import android.content.Intent
import io.flutter.plugin.common.BinaryMessenger
import io.flutter.plugin.common.MethodChannel
import java.util.concurrent.Executors

/** Process-lifetime disk queue. Capture callbacks may finish after the Activity is recreated. */
object ScanWork { val executor = Executors.newSingleThreadExecutor() }

class HyzenLiveScanner(private val activity:MainActivity,messenger:BinaryMessenger) {
    private var pending:MethodChannel.Result?=null
    private val channel=MethodChannel(messenger,"com.hyzen.pharmd/live_scanner")
    init{channel.setMethodCallHandler{call,result->
        if(call.method!="scan"){result.notImplemented();return@setMethodCallHandler}
        if(active){result.error("busy","Finish the current scan first.",null);return@setMethodCallHandler}
        active=true;pending=result
        try{activity.startActivityForResult(Intent(activity,HyzenScanActivity::class.java),REQUEST)}
        catch(_:Exception){active=false;pending=null;result.error("camera","Camera preview unavailable. Use the other scanner or gallery.",null)}
    }}
    fun receive(code:Int,resultCode:Int,data:Intent?):Boolean{
        if(code!=REQUEST)return false
        active=false;val result=pending;pending=null
        ScanWork.executor.execute{
            try{val pages=ScanDraftStore(activity.applicationContext).recover()
                activity.runOnUiThread{result?.success(mapOf("pages" to pages,"action" to (data?.getStringExtra("action")?:"review")))}}
            catch(_:Exception){activity.runOnUiThread{result?.error("camera","Could not restore the scan. Earlier pages remain saved.",null)}}
        }
        return true
    }
    fun close(){pending=null}
    companion object{const val REQUEST=8894;@Volatile var active=false;private set}
}

package com.hyzen.pharmd

import android.app.Activity
import android.content.ClipData
import android.content.Context
import android.content.Intent
import android.graphics.Bitmap
import android.graphics.Matrix
import android.graphics.Canvas
import android.graphics.Paint
import android.graphics.ColorMatrix
import android.graphics.ColorMatrixColorFilter
import android.provider.MediaStore
import androidx.core.content.FileProvider
import io.flutter.plugin.common.BinaryMessenger
import io.flutter.plugin.common.MethodChannel
import org.json.JSONArray
import java.io.File
import java.util.concurrent.Executors

/** Uses the installed camera app, without an app camera permission or a heavy
 * Play-services scanning Activity. Each confirmed capture appends one page. */
class HyzenCameraCapture(private val activity: MainActivity, messenger: BinaryMessenger) {
    private val store = ScanDraftStore(activity)
    private val worker = Executors.newSingleThreadExecutor()
    private val channel = MethodChannel(messenger, "com.hyzen.pharmd/camera_pages")
    private var pending: MethodChannel.Result? = null
    private var busy = false
    init {
        channel.setMethodCallHandler { call, result ->
            if (HyzenLiveScanner.active && call.method != "needsRecovery") { result.error("busy", "Finish the live camera first.", null); return@setMethodCallHandler }
            if (call.method == "capture") {
                if (activity.checkSelfPermission(android.Manifest.permission.CAMERA) != android.content.pm.PackageManager.PERMISSION_GRANTED) {
                    result.error("camera_permission", "Camera access is needed. Use Scan to allow it, or choose gallery images.", null); return@setMethodCallHandler
                }
                if (pending != null || busy) { result.error("busy", "Finish this page first.", null); return@setMethodCallHandler }
                try {
                    val file = store.newCapture()
                    val uri = FileProvider.getUriForFile(activity, "${activity.packageName}.updates", file)
                    val intent = Intent(MediaStore.ACTION_IMAGE_CAPTURE).apply {
                        putExtra(MediaStore.EXTRA_OUTPUT, uri)
                        clipData = ClipData.newRawUri("Scan page", uri)
                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
                    }
                    pending = result
                    activity.startActivityForResult(intent, REQUEST)
                } catch (_: Exception) {
                    store.finishCapture(false); store.acknowledge(); pending = null
                    result.error("camera", "Camera unavailable. Choose gallery images instead.", null)
                }
                return@setMethodCallHandler
            }
            if (busy) { result.error("busy", "Preparing your page…", null); return@setMethodCallHandler }
            busy = true
            worker.execute {
                try {
                    val answer: Any = when (call.method) {
                        "archive" -> store.archive(call.argument<String>("id") ?: "")
                        "openArchive" -> store.openArchive(call.argument<String>("id") ?: "")
                        "deleteArchive" -> store.deleteArchive(call.argument<String>("id") ?: "")
                        "needsRecovery" -> store.needsRecovery() && pending == null
                        "recover" -> store.recover().also { store.acknowledge() }
                        "addImages" -> store.add(call.argument<List<String>>("paths") ?: emptyList())
                        "replace" -> store.replace(call.argument<List<String>>("paths") ?: emptyList())
                        "undoRemoval" -> store.undoRemoval()
                        "undo" -> store.undo(call.argument<String>("path") ?: "")
                        "reset" -> store.reset(call.argument<String>("path") ?: "")
                        "editPreview" -> store.editPreview(call.argument<String>("path") ?: "")
                        "originalInfo" -> store.originalInfo(call.argument<String>("path") ?: "")
                        "rotate" -> store.rotate(call.argument<String>("path") ?: "")
                        "edit" -> store.edit(call.argument<List<String>>("paths") ?: emptyList(), call.argument<String>("filter") ?: "original", call.argument<List<Double>>("crop"), call.argument<List<Double>>("quad"), call.argument<Number>("brightness")?.toDouble() ?: 0.0, call.argument<Number>("contrast")?.toDouble() ?: 1.0)
                        "clear" -> { store.clear(); true }
                        else -> { activity.runOnUiThread { busy = false; result.notImplemented() }; return@execute }
                    }
                    activity.runOnUiThread { busy = false; result.success(answer) }
                } catch (e: Throwable) {
                    activity.runOnUiThread { busy = false; result.error("scan_page", when(call.method) {
                        "archive" -> "PDF saved, but editable backup failed. Your current draft is retained."
                        "openArchive" -> "Could not reopen this scan. Finish any current draft first; older scans may not have editable originals."
                        else -> "Could not prepare this page. Your earlier pages are safe."
                    }, null) }
                }
            }
        }
    }
    fun receive(code: Int, resultCode: Int): Boolean {
        if (code != REQUEST) return false
        val result = pending; pending = null; busy = true
        worker.execute {
            try {
                val pages = store.finishCapture(resultCode == Activity.RESULT_OK)
                if (result != null) store.acknowledge()
                activity.runOnUiThread { busy = false; result?.success(pages); channel.invokeMethod("draftReady", null) }
            } catch (_: Throwable) {
                activity.runOnUiThread { busy = false; result?.error("capture", "Could not add this page. Your earlier pages are safe.", null) }
            }
        }
        return true
    }
    fun close() { pending = null; worker.shutdown() }
    companion object { const val REQUEST = 8892 }
}

package com.hyzen.pharmd

import android.app.Activity
import android.content.Intent
import com.google.mlkit.vision.documentscanner.GmsDocumentScannerOptions
import com.google.mlkit.vision.documentscanner.GmsDocumentScanning
import com.google.mlkit.vision.documentscanner.GmsDocumentScanningResult
import io.flutter.plugin.common.BinaryMessenger
import io.flutter.plugin.common.MethodChannel
import java.io.File
import java.util.concurrent.Executors

/** Google's native document viewfinder supplies auto/manual capture, page-edge
 * correction, cleanup and multi-page review. Only JPEG output is requested:
 * Hyzen composes the final PDF once, after its durable page review. */
class HyzenDocumentScanner(private val activity: MainActivity, messenger: BinaryMessenger) {
    private val store = ScanDraftStore(activity)
    private var pending: MethodChannel.Result? = null
    private var active = false
    private val worker = Executors.newSingleThreadExecutor()
    private val channel = MethodChannel(messenger, "com.hyzen.pharmd/document_scanner")
    private val cameraChannel = MethodChannel(messenger, "com.hyzen.pharmd/camera_pages")
    private val requestCode = 8891
    init {
        channel.setMethodCallHandler { call, result ->
            if (call.method != "scan") { result.notImplemented(); return@setMethodCallHandler }
            if (HyzenLiveScanner.active) { result.error("busy", "Finish the live camera first.", null); return@setMethodCallHandler }
            if (active) { result.error("busy", "Finish the current scan first.", null); return@setMethodCallHandler }
            val available = 30 - store.pages().size
            if (available <= 0) { result.error("limit", "Save these 30 pages before scanning more.", null); return@setMethodCallHandler }
            pending = result
            active = true
            store.beginScan()
            val options = GmsDocumentScannerOptions.Builder()
                .setGalleryImportAllowed(true).setPageLimit(available)
                .setResultFormats(GmsDocumentScannerOptions.RESULT_FORMAT_JPEG)
                .setScannerMode(GmsDocumentScannerOptions.SCANNER_MODE_FULL).build()
            GmsDocumentScanning.getClient(options).getStartScanIntent(activity)
                .addOnSuccessListener { sender ->
                    if (active && !activity.isFinishing) {
                        try { activity.startIntentSenderForResult(sender, requestCode, null, 0, 0, 0) }
                        catch (_: Exception) { fail() }
                    }
                }.addOnFailureListener { fail() }
        }
    }
    private fun fail() {
        store.acknowledge()
        pending?.error("scanner_unavailable", "Document scanner is unavailable. Update Google Play services, or choose the basic camera / gallery.", null)
        pending = null; active = false
    }
    fun receive(code: Int, resultCode: Int, intent: Intent?): Boolean {
        if (code != requestCode) return false
        // Process results even when Android recreated this Activity and there
        // is no live MethodChannel callback to the previous Flutter isolate.
        val result = pending; pending = null
        if (resultCode != Activity.RESULT_OK) {
            active = false; store.acknowledge(); result?.success(store.pages()); return true
        }
        worker.execute {
            val staged = mutableListOf<File>()
            try {
                val pages = GmsDocumentScanningResult.fromActivityResultIntent(intent)?.pages
                    ?: error("No scanned pages returned")
                require(pages.isNotEmpty() && pages.size + store.pages().size <= 30)
                for (page in pages) {
                    val file = File.createTempFile("scan_result_", ".jpg", activity.cacheDir)
                    staged.add(file)
                    activity.contentResolver.openInputStream(page.imageUri)?.use { input ->
                        file.outputStream().use { output ->
                            val buffer = ByteArray(65536); var total = 0L
                            while (true) {
                                val n = input.read(buffer); if (n < 0) break
                                total += n; require(total <= 40L * 1024 * 1024)
                                output.write(buffer, 0, n)
                            }
                        }
                    } ?: error("Scan unavailable")
                }
                val saved = store.addProcessed(staged.map { it.path })
                // Keep recovery flag until the new Flutter screen reads it.
                activity.runOnUiThread {
                    active = false
                    result?.success(saved)
                    cameraChannel.invokeMethod("draftReady", null)
                }
            } catch (_: Throwable) {
                activity.runOnUiThread {
                    active = false
                    result?.error("scan", "Could not add scanned pages. Your earlier pages are safe.", null)
                    cameraChannel.invokeMethod("draftReady", null)
                }
            } finally { staged.forEach { it.delete() } }
        }
        return true
    }
    fun close() { pending = null; worker.shutdown() }
}

package com.hyzen.pharmd

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Matrix
import android.graphics.Paint
import android.graphics.Path
import android.graphics.RectF
import android.graphics.Typeface
import android.graphics.pdf.PdfDocument
import android.graphics.pdf.PdfRenderer
import android.os.ParcelFileDescriptor
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import java.io.File
import java.io.ByteArrayOutputStream
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream
import java.util.concurrent.Executors

/** Local PDF operations. Pages are rasterized so input documents are never modified. */
class StudioPdfEngine(private val activity: MainActivity, engine: FlutterEngine) {
    private val worker = Executors.newSingleThreadExecutor()
    private val documentOps = StudioDocumentOps(activity)

    init {
        MethodChannel(engine.dartExecutor.binaryMessenger, "com.hyzen.pharmd/pdf_studio")
            .setMethodCallHandler { call, result ->
                worker.execute {
                    try {
                        val answer: Any = when (call.method) {
                            "pageCount" -> {
                                val path = call.argument<String>("path") ?: error("Missing PDF path")
                                ParcelFileDescriptor.open(File(path), ParcelFileDescriptor.MODE_READ_ONLY).use { fd ->
                                    PdfRenderer(fd).use { it.pageCount }
                                }
                            }
                            "compose" -> {
                                val pages = call.argument<List<Map<String, Any?>>>("pages") ?: error("No pages selected")
                                if (call.argument<Boolean>("flatten") == true) compose(pages) else documentOps.compose(pages)
                            }
                            "protect" -> documentOps.protect(call.argument<String>("path") ?: error("Missing PDF"), call.argument<String>("password") ?: error("Missing password"))
                            "ocr" -> documentOps.ocr(call.argument<String>("path") ?: error("Missing PDF"))
                            "compress" -> documentOps.compress(call.argument<String>("path") ?: error("Missing PDF"), call.argument<String>("preset") ?: "balanced")
                            "richDocument" -> StudioRichWriter(activity).write(call.argument<List<Map<String,Any?>>>("blocks") ?: error("Missing document"),call.argument<String>("format") ?: "pdf")
                            "imagesToPdf" -> {
                                check(!HyzenLiveScanner.active) { "Finish the live camera before exporting." }
                                val paths = call.argument<List<String>>("paths") ?: error("No images selected")
                                if (call.argument<Boolean>("scanDraft") == true) ScanDraftStore(activity).exportPdf(paths, call.argument<Boolean>("highQuality") == true, call.argument<String>("paper") ?: "a4", call.argument<String>("orientation") ?: "auto", call.argument<Int>("margin") ?: 16) else documentOps.imagesToPdf(paths, paper = call.argument<String>("paper") ?: "a4", orientation = call.argument<String>("orientation") ?: "auto", margin = call.argument<Int>("margin") ?: 16)
                            }
                            "textToPdf" -> textToPdf(call.argument<String>("text") ?: "")
                            "textToDocx" -> textToDocx(call.argument<String>("text") ?: "")
                            "textFile" -> {
                                File.createTempFile("studio_note_", ".txt", activity.cacheDir).apply {
                                    writeText(call.argument<String>("text") ?: "")
                                }.absolutePath
                            }
                            "readText" -> {
                                val source = File(call.argument<String>("path") ?: error("Missing document"))
                                require(source.length() <= 2_000_000L) { "Text file is too large." }
                                source.readText(Charsets.UTF_8)
                            }
                            "pagesToImages" -> pagesToImages(
                                call.argument<String>("path") ?: error("Missing PDF"),
                                call.argument<String>("format") ?: "png"
                            )
                            "renderPage" -> renderPage(
                                call.argument<String>("path") ?: error("Missing PDF"),
                                call.argument<Int>("index") ?: 0,
                                call.argument<Int>("maxEdge") ?: 1800
                            )
                            "getEditState" -> stateFile(call.argument<String>("path") ?: error("Missing state")).readText()
                            "setEditState" -> {
                                val content = call.argument<String>("json") ?: error("Missing annotation state")
                                require(content.length <= 500_000) { "Too many annotations" }
                                val target = stateFile(call.argument<String>("path") ?: error("Missing state"))
                                val partial = File(target.parentFile, "${target.name}.part")
                                try {
                                    partial.writeText(content)
                                    require(partial.renameTo(target)) { "Could not save annotations" }
                                } finally { if (partial.exists()) partial.delete() }
                                true
                            }
                            else -> {
                                activity.runOnUiThread { result.notImplemented() }
                                return@execute
                            }
                        }
                        activity.runOnUiThread { result.success(answer) }
                    } catch (_: OutOfMemoryError) {
                        activity.runOnUiThread { result.error("pdf_memory", "Not enough memory. Save fewer pages; your draft is safe.", null) }
                    } catch (e: Exception) {
                        activity.runOnUiThread {
                            result.error("pdf_studio", e.message ?: "PDF operation failed", null)
                        }
                    }
                }
            }
    }

    private fun output(): File = File.createTempFile("studio_", ".pdf", activity.cacheDir)

    private fun compose(pages: List<Map<String, Any?>>): String {
        require(pages.isNotEmpty() && pages.size <= 150) { "Select 1–150 pages." }
        val destination = output()
        val document = PdfDocument()
        val inputs = mutableMapOf<String, Pair<ParcelFileDescriptor, PdfRenderer>>()
        try {
            pages.forEachIndexed { position, spec ->
                if (spec["blank"] == true) {
                    val blank = document.startPage(PdfDocument.PageInfo.Builder(595, 842, position + 1).create())
                    blank.canvas.drawColor(Color.WHITE)
                    document.finishPage(blank)
                    return@forEachIndexed
                }
                val source = File(spec["path"] as? String ?: error("Missing source"))
                val index = (spec["page"] as? Number)?.toInt() ?: error("Missing page index")
                val rotation = ((spec["rotation"] as? Number)?.toInt() ?: 0).rem(360)
                require(rotation == 0 || rotation == 90 || rotation == 180 || rotation == 270) { "Invalid rotation" }
                val renderer = inputs.getOrPut(source.canonicalPath) {
                    val fd = ParcelFileDescriptor.open(source, ParcelFileDescriptor.MODE_READ_ONLY)
                    try { fd to PdfRenderer(fd) }
                    catch (e: Exception) { fd.close(); throw e }
                }.second
                        require(index in 0 until renderer.pageCount) { "Page out of range" }
                        renderer.openPage(index).use { page ->
                            val sideways = rotation == 90 || rotation == 270
                            val width = if (sideways) page.height else page.width
                            val height = if (sideways) page.width else page.height
                            val scale = minOf(2f, 2000f / maxOf(page.width, page.height))
                            val bitmap = Bitmap.createBitmap(
                                maxOf(1, (page.width * scale).toInt()),
                                maxOf(1, (page.height * scale).toInt()), Bitmap.Config.ARGB_8888
                            )
                            try {
                                bitmap.eraseColor(Color.WHITE)
                                page.render(bitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY)
                                val info = PdfDocument.PageInfo.Builder(width, height, position + 1).create()
                                val target = document.startPage(info)
                                val canvas = target.canvas
                                canvas.drawColor(Color.WHITE)
                                canvas.save()
                                when (rotation) {
                                    90 -> { canvas.translate(width.toFloat(), 0f); canvas.rotate(90f) }
                                    180 -> { canvas.translate(width.toFloat(), height.toFloat()); canvas.rotate(180f) }
                                    270 -> { canvas.translate(0f, height.toFloat()); canvas.rotate(270f) }
                                }
                                canvas.drawBitmap(bitmap, null, RectF(0f, 0f, page.width.toFloat(), page.height.toFloat()), Paint(Paint.FILTER_BITMAP_FLAG))
                                canvas.restore()
                                @Suppress("UNCHECKED_CAST")
                                val marks = spec["annotations"] as? List<Map<String, Any?>> ?: emptyList()
                                paintAnnotations(canvas, marks, width.toFloat(), height.toFloat())
                                document.finishPage(target)
                            } finally { bitmap.recycle() }
                        }
            }
            destination.outputStream().use { document.writeTo(it) }
            return destination.absolutePath
        } catch (e: Exception) {
            destination.delete()
            throw e
        } finally {
            document.close()
            inputs.values.forEach { (fd, renderer) ->
                try { renderer.close() } finally { fd.close() }
            }
        }
    }

    private fun imagesToPdf(paths: List<String>): String {
        require(paths.isNotEmpty() && paths.size <= 50) { "Choose 1–50 images." }
        val destination = output()
        val document = PdfDocument()
        try {
            paths.forEachIndexed { index, path ->
                val bitmap = StudioImages.load(path)
                try {
                    val portrait = bitmap.height >= bitmap.width
                    val width = if (portrait) 595 else 842
                    val height = if (portrait) 842 else 595
                    val page = document.startPage(PdfDocument.PageInfo.Builder(width, height, index + 1).create())
                    page.canvas.drawColor(Color.WHITE)
                    val factor = minOf((width - 40f) / bitmap.width, (height - 40f) / bitmap.height)
                    val w = bitmap.width * factor
                    val h = bitmap.height * factor
                    page.canvas.drawBitmap(bitmap, null, RectF((width - w) / 2, (height - h) / 2, (width + w) / 2, (height + h) / 2), Paint(Paint.FILTER_BITMAP_FLAG))
                    document.finishPage(page)
                } finally { bitmap.recycle() }
            }
            destination.outputStream().use { document.writeTo(it) }
            return destination.absolutePath
        } catch (e: Exception) { destination.delete(); throw e }
        finally { document.close() }
    }

    private fun textToPdf(text: String): String {
        require(text.length <= 200_000) { "Document is too long." }
        val destination = output()
        val document = PdfDocument()
        val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply { color = Color.BLACK; textSize = 12f }
        try {
            val lines = mutableListOf<String>()
            text.replace("\r\n", "\n").split('\n').forEach { paragraph ->
                var line = ""
                paragraph.split(' ').forEach { word ->
                    val next = if (line.isEmpty()) word else "$line $word"
                    if (paint.measureText(next) > 510f && line.isNotEmpty()) { lines.add(line); line = word }
                    else line = next
                }
                lines.add(line)
            }
            require(lines.size <= 5000) { "Document is too long." }
            lines.chunked(48).forEachIndexed { i, chunk ->
                val page = document.startPage(PdfDocument.PageInfo.Builder(595, 842, i + 1).create())
                page.canvas.drawColor(Color.WHITE)
                chunk.forEachIndexed { row, line -> page.canvas.drawText(line.take(400), 42f, 48f + row * 16f, paint) }
                document.finishPage(page)
            }
            destination.outputStream().use { document.writeTo(it) }
            return destination.absolutePath
        } catch (e: Exception) { destination.delete(); throw e }
        finally { document.close() }
    }

    private fun textToDocx(text: String): String {
        require(text.length <= 200_000) { "Document is too long." }
        val destination = File.createTempFile("studio_document_", ".docx", activity.cacheDir)
        fun escape(value: String): String = value.replace("&", "&amp;")
            .replace("<", "&lt;").replace(">", "&gt;")
            .replace("\"", "&quot;").replace("'", "&apos;")
        val paragraphs = text.replace("\r\n", "\n").split('\n').joinToString("") { line ->
            "<w:p><w:r><w:t xml:space=\"preserve\">${escape(line.filter { it == '\t' || it >= ' ' })}</w:t></w:r></w:p>"
        }
        try {
            ZipOutputStream(destination.outputStream().buffered()).use { zip ->
                fun entry(name: String, xml: String) {
                    zip.putNextEntry(ZipEntry(name))
                    zip.write(xml.toByteArray(Charsets.UTF_8))
                    zip.closeEntry()
                }
                entry("[Content_Types].xml", """<?xml version="1.0" encoding="UTF-8"?>
                    <Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
                    <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
                    <Default Extension="xml" ContentType="application/xml"/>
                    <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
                    </Types>""".trimIndent())
                entry("_rels/.rels", """<?xml version="1.0" encoding="UTF-8"?>
                    <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
                    <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
                    </Relationships>""".trimIndent())
                entry("word/document.xml", """<?xml version="1.0" encoding="UTF-8"?>
                    <w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
                    <w:body>$paragraphs<w:sectPr/></w:body></w:document>""".trimIndent())
            }
            return destination.absolutePath
        } catch (e: Exception) { destination.delete(); throw e }
    }

    private fun pagesToImages(path: String, format: String): String {
        require(format == "png" || format == "jpg") { "Choose PNG or JPG." }
        val archive = File.createTempFile("studio_pages_", ".zip", activity.cacheDir)
        try {
            ParcelFileDescriptor.open(File(path), ParcelFileDescriptor.MODE_READ_ONLY).use { fd ->
                PdfRenderer(fd).use { renderer ->
                    require(renderer.pageCount <= 150) { "Export up to 150 pages." }
                    ZipOutputStream(archive.outputStream().buffered()).use { zip ->
                        for (index in 0 until renderer.pageCount) {
                            renderer.openPage(index).use { page ->
                                val factor = minOf(2f, 2000f / maxOf(page.width, page.height))
                                val bitmap = Bitmap.createBitmap(
                                    maxOf(1, (page.width * factor).toInt()),
                                    maxOf(1, (page.height * factor).toInt()), Bitmap.Config.ARGB_8888
                                )
                                try {
                                    bitmap.eraseColor(Color.WHITE)
                                    page.render(bitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY)
                                    zip.putNextEntry(ZipEntry("page_${(index + 1).toString().padStart(3, '0')}.$format"))
                                    bitmap.compress(if (format == "png") Bitmap.CompressFormat.PNG else Bitmap.CompressFormat.JPEG, 85, zip)
                                    zip.closeEntry()
                                } finally { bitmap.recycle() }
                            }
                        }
                    }
                }
            }
            return archive.absolutePath
        } catch (e: Exception) { archive.delete(); throw e }
    }

    private fun stateFile(path: String): File {
        val root = File(activity.filesDir, "pdf_studio/state").canonicalFile
        val target = File(path).canonicalFile
        require(target.parentFile == root && target.name.endsWith("_state.json") && target.isFile) {
            "Annotation state is unavailable"
        }
        return target
    }

    private fun renderPage(path: String, index: Int, maxEdge: Int = 1800): Map<String, Any> =
        PdfPagePreviewRenderer.render(path, index, maxEdge)

    private fun paintAnnotations(canvas: Canvas, marks: List<Map<String, Any?>>, width: Float, height: Float) {
        for (mark in marks.take(200)) {
            val type = mark["tool"] as? String ?: continue
            val raw = mark["points"] as? List<*> ?: continue
            val points = raw.mapNotNull { pair ->
                val values = pair as? List<*> ?: return@mapNotNull null
                if (values.size != 2) return@mapNotNull null
                val x = (values[0] as? Number)?.toFloat() ?: return@mapNotNull null
                val y = (values[1] as? Number)?.toFloat() ?: return@mapNotNull null
                if (!x.isFinite() || !y.isFinite()) return@mapNotNull null
                (x.coerceIn(0f, 1f) * width) to (y.coerceIn(0f, 1f) * height)
            }
            if (points.isEmpty()) continue
            val color = (mark["color"] as? Number)?.toInt() ?: Color.rgb(103, 49, 210)
            val stroke = ((mark["stroke"] as? Number)?.toFloat() ?: 3f).coerceIn(1f, 32f)
            val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                this.color = if (type == "highlight") (color and 0x00FFFFFF) or 0x66000000 else color
                style = Paint.Style.STROKE
                strokeWidth = if (type == "highlight") stroke * 5f else stroke
                strokeCap = Paint.Cap.ROUND
                strokeJoin = Paint.Join.ROUND
            }
            val first = points.first()
            val last = points.last()
            when (type) {
                "ink", "highlight", "underline", "strike", "arrow" -> {
                    val line = Path().apply {
                        moveTo(first.first, first.second)
                        points.drop(1).forEach { lineTo(it.first, it.second) }
                    }
                    canvas.drawPath(line, paint)
                    if(type=="arrow") {
                        val angle=kotlin.math.atan2(last.second-first.second,last.first-first.first)
                        val head=maxOf(10f,stroke*4)
                        canvas.drawLine(last.first,last.second,last.first-head*kotlin.math.cos(angle-.5f),last.second-head*kotlin.math.sin(angle-.5f),paint)
                        canvas.drawLine(last.first,last.second,last.first-head*kotlin.math.cos(angle+.5f),last.second-head*kotlin.math.sin(angle+.5f),paint)
                    }
                }
                "rectangle" -> canvas.drawRect(minOf(first.first, last.first), minOf(first.second, last.second),
                    maxOf(first.first, last.first), maxOf(first.second, last.second), paint)
                "circle" -> canvas.drawOval(RectF(minOf(first.first, last.first), minOf(first.second, last.second),
                    maxOf(first.first, last.first), maxOf(first.second, last.second)), paint)
                "text", "signature", "note" -> {
                    val label = (mark["text"] as? String ?: "").take(90)
                    paint.style = Paint.Style.FILL
                    paint.textSize = if (type == "signature") 24f else 14f
                    if (type == "signature") paint.typeface = Typeface.create(Typeface.SERIF, Typeface.ITALIC)
                    canvas.drawText(label, first.first, first.second + paint.textSize, paint)
                }
            }
        }
    }

    fun close() { worker.shutdown() }
}

package com.hyzen.pharmd

import android.app.Activity
import android.content.Intent
import android.net.Uri
import android.provider.OpenableColumns
import android.graphics.BitmapFactory
import android.graphics.Bitmap
import android.graphics.Matrix
import android.media.ExifInterface
import java.io.File
import androidx.core.content.FileProvider
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import java.io.ByteArrayOutputStream
import java.util.concurrent.Executors

class MainActivity : FlutterActivity() {
    private var externalFiles: HyzenExternalFiles? = null
    private var studioPdfEngine: StudioPdfEngine? = null
    private var documentScanner: HyzenDocumentScanner? = null
    private var liveScanner: HyzenLiveScanner? = null
    private var cameraCapture: HyzenCameraCapture? = null
    private val pickCode = 8711
    private val saveCode = 8712
    private val imageCode = 8713
    private val studioPickCode = 8714
    private var exportPath: String? = null
    private var dataSelection=false
    private var pending: MethodChannel.Result? = null
    private var templateText: String? = null
    private val fileWorker = Executors.newSingleThreadExecutor()

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        HyzenUpdater(this, flutterEngine.dartExecutor.binaryMessenger)
        externalFiles = HyzenExternalFiles(this, flutterEngine.dartExecutor.binaryMessenger)
        studioPdfEngine = StudioPdfEngine(this, flutterEngine)
        documentScanner = HyzenDocumentScanner(this, flutterEngine.dartExecutor.binaryMessenger)
        liveScanner = HyzenLiveScanner(this, flutterEngine.dartExecutor.binaryMessenger)
        cameraCapture = HyzenCameraCapture(this, flutterEngine.dartExecutor.binaryMessenger)
        externalFiles?.receive(intent)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "com.hyzen.pharmd/csv_files")
            .setMethodCallHandler { call, result ->
                if (pending != null) {
                    result.error("busy", "Finish the current file selection first.", null)
                    return@setMethodCallHandler
                }
                when (call.method) {
                    "pickCsvFiles", "pickDataFiles" -> {
                        dataSelection=call.method=="pickDataFiles"
                        pending = result
                        try {
                            val intent = Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
                                addCategory(Intent.CATEGORY_OPENABLE)
                                type = "*/*"
                                putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true)
                                putExtra(Intent.EXTRA_MIME_TYPES, arrayOf("text/csv", "text/comma-separated-values", "application/csv", "application/vnd.ms-excel", "text/plain", "application/octet-stream", "application/json", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))
                            }
                            startActivityForResult(intent, pickCode)
                        } catch (e: Exception) { finishError("picker", "Could not open the file picker.") }
                    }
                    "saveCsvTemplate" -> {
                        pending = result
                        templateText = call.argument<String>("text")
                        try {
                            startActivityForResult(Intent(Intent.ACTION_CREATE_DOCUMENT).apply {
                                addCategory(Intent.CATEGORY_OPENABLE)
                                type = "text/csv"
                                putExtra(Intent.EXTRA_TITLE, "hyzen_bulk_import_template.csv")
                            }, saveCode)
                        } catch (e: Exception) { finishError("save", "Could not choose a save location.") }
                    }
                    "pickImage" -> {
                        pending=result
                        try { startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
                            addCategory(Intent.CATEGORY_OPENABLE);type="image/*"
                            putExtra(Intent.EXTRA_MIME_TYPES,arrayOf("image/jpeg","image/png","image/webp"))
                        },imageCode) } catch (e:Exception){finishError("picker","Could not open photos.")}
                    }
                    "pickStudioFiles" -> {
                        pending = result
                        try {
                            startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
                                addCategory(Intent.CATEGORY_OPENABLE)
                                type = "*/*"
                                putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true)
                                putExtra(Intent.EXTRA_MIME_TYPES, arrayOf(
                                    "application/pdf", "image/jpeg", "image/png", "image/webp", "text/plain", "text/markdown", "application/rtf", "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
                                ))
                            }, studioPickCode)
                        } catch (e: Exception) { finishError("picker", "Could not open documents.") }
                    }
                    "saveFile", "exportFile" -> {
                        pending=result
                        templateText=call.argument<String>("text")
                        exportPath=call.argument<String>("path")
                        try {startActivityForResult(Intent(Intent.ACTION_CREATE_DOCUMENT).apply {
                            addCategory(Intent.CATEGORY_OPENABLE)
                            type=call.argument<String>("mime") ?: "text/plain"
                            putExtra(Intent.EXTRA_TITLE,call.argument<String>("name") ?: "hyzen_export.txt")
                        },saveCode)}catch(e:Exception){finishError("save","Could not save the file.")}
                    }
                    "shareFile" -> {
                        val path = call.argument<String>("path")
                        val name = call.argument<String>("name") ?: "document"
                        val mime = call.argument<String>("mime") ?: "application/octet-stream"
                        if (path.isNullOrBlank() || !File(path).isFile) {
                            result.error("share", "This document is no longer available.", null)
                        } else {
                            fileWorker.execute {
                                var shared: File? = null
                                try {
                                    val folder = File(cacheDir, "hyzen_shares").apply { mkdirs() }
                                    val safeName = name.replace(Regex("[^A-Za-z0-9._-]"), "_").take(120)
                                    val shareCopy = File(folder, "${System.currentTimeMillis()}_$safeName")
                                    shared = shareCopy
                                    File(path).inputStream().use { input ->
                                        shareCopy.outputStream().use { output -> input.copyTo(output) }
                                    }
                                    val uri = FileProvider.getUriForFile(this, "$packageName.updates", shareCopy)
                                    val send = Intent(Intent.ACTION_SEND).apply {
                                        type = mime
                                        putExtra(Intent.EXTRA_STREAM, uri)
                                        putExtra(Intent.EXTRA_TITLE, name)
                                        clipData = android.content.ClipData.newRawUri(name, uri)
                                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                                    }
                                    runOnUiThread {
                                        try {
                                            startActivity(Intent.createChooser(send, "Share $name"))
                                            result.success(true)
                                        } catch (e: Exception) {
                                            shared?.delete()
                                            result.error("share", "No app can share this file.", null)
                                        }
                                    }
                                } catch (e: Exception) {
                                    shared?.delete()
                                    runOnUiThread { result.error("share", "Could not prepare this file to share.", null) }
                                }
                            }
                        }
                    }
                    else -> result.notImplemented()
                }
            }
    }
    private fun finishError(code: String, message: String) {
        val result = pending
        pending = null
        templateText = null
        exportPath = null
        result?.error(code, message, null)
    }
    private fun fileName(uri: Uri): String {
        contentResolver.query(uri, arrayOf(OpenableColumns.DISPLAY_NAME), null, null, null)?.use { cursor ->
            if (cursor.moveToFirst()) return cursor.getString(0) ?: "import.csv"
        }
        return uri.lastPathSegment ?: "import.csv"
    }
    @Deprecated("Activity result bridge retained for Flutter file picker")
    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (liveScanner?.receive(requestCode, resultCode, data) == true) return
        if (cameraCapture?.receive(requestCode, resultCode) == true) return
        if (documentScanner?.receive(requestCode, resultCode, data) == true) return
        if (requestCode != pickCode && requestCode != saveCode && requestCode != imageCode && requestCode != studioPickCode) return
        val result = pending ?: return
        if (resultCode != Activity.RESULT_OK) {
            pending = null
            templateText = null
        exportPath = null
            result.success(if (requestCode == pickCode || requestCode == studioPickCode) emptyList<Map<String, Any>>() else if(requestCode==imageCode)null else false)
            return
        }
        val text = templateText ?: ""
        val sourcePath=exportPath
        fileWorker.execute {
            try {
                val response: Any
                if (requestCode == saveCode) {
                    val uri = data?.data ?: throw IllegalStateException("No destination selected.")
                    val stream = contentResolver.openOutputStream(uri, "wt") ?: throw IllegalStateException("Could not open destination.")
                    stream.use { target ->
                        if(sourcePath!=null)File(sourcePath).inputStream().use{it.copyTo(target)}
                        else target.write(text.toByteArray(Charsets.UTF_8))
                    }
                    response = true
                } else if (requestCode == studioPickCode) {
                    val uris = mutableListOf<Uri>()
                    val clips = data?.clipData
                    if (clips != null) {
                        if (clips.itemCount > 20) throw IllegalStateException("Choose at most 20 files.")
                        for (i in 0 until clips.itemCount) uris.add(clips.getItemAt(i).uri)
                    } else data?.data?.let { uris.add(it) }
                    response = uris.map { uri ->
                        val name = fileName(uri)
                        val extension = name.substringAfterLast('.', "").lowercase()
                        if (extension !in setOf("pdf", "jpg", "jpeg", "png", "webp", "txt", "md", "rtf", "docx"))
                            throw IllegalStateException("Choose PDF, image or text files.")
                        val copy = File.createTempFile("studio_pick_", ".$extension", cacheDir)
                        try {
                            var size = 0L
                            (contentResolver.openInputStream(uri) ?: error("Could not read $name")).use { input ->
                                copy.outputStream().use { target ->
                                    val buffer = ByteArray(65536)
                                    var count = input.read(buffer)
                                    while (count != -1) {
                                        size += count
                                        if (size > 150L * 1024 * 1024) error("Files must be smaller than 150 MB.")
                                        target.write(buffer, 0, count)
                                        count = input.read(buffer)
                                    }
                                }
                            }
                            mapOf("name" to name, "path" to copy.absolutePath)
                        } catch (e: Exception) { copy.delete(); throw e }
                    }
                } else if(requestCode==imageCode){
                    val uri=data?.data ?: throw IllegalStateException("No image selected.")
                    val input=contentResolver.openInputStream(uri) ?: throw IllegalStateException("Could not read photo.")
                    val dataBytes=ByteArrayOutputStream()
                    input.use { val buffer=ByteArray(8192);var count=it.read(buffer)
                        while(count!=-1){if(dataBytes.size()+count>12*1024*1024)throw IllegalStateException("Choose a photo smaller than 12 MB.");dataBytes.write(buffer,0,count);count=it.read(buffer)}
                    }
                    val bytes=dataBytes.toByteArray()
                    if(bytes.size>12*1024*1024)throw IllegalStateException("Choose a photo smaller than 12 MB.")
                    val options=BitmapFactory.Options().apply{inJustDecodeBounds=true}
                    BitmapFactory.decodeByteArray(bytes,0,bytes.size,options)
                    if(options.outWidth<=0||options.outHeight<=0)throw IllegalStateException("Choose a JPEG, PNG or WebP photo.")
                    options.inSampleSize=1
                    while(maxOf(options.outWidth,options.outHeight)/options.inSampleSize>1600)options.inSampleSize*=2
                    options.inJustDecodeBounds=false
                    var bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.size,options) ?: throw IllegalStateException("Photo could not be decoded.")
                    val rotation=try { val exif=ExifInterface(bytes.inputStream()); when(exif.getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL)) {
                        ExifInterface.ORIENTATION_ROTATE_90->90f;ExifInterface.ORIENTATION_ROTATE_180->180f;ExifInterface.ORIENTATION_ROTATE_270->270f;else->0f
                    }}catch(e:Exception){0f}
                    if(rotation!=0f){val rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.width,bitmap.height,Matrix().apply{postRotate(rotation)},true);if(rotated!==bitmap)bitmap.recycle();bitmap=rotated}
                    val output=ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,88,output);bitmap.recycle()
                    response=mapOf("name" to "hyzen_photo.jpg","bytes" to output.toByteArray())
                } else {
                    val uris = mutableListOf<Uri>()
                    val clips = data?.clipData
                    if (clips != null) {
                        if (clips.itemCount > 20) throw IllegalStateException("Choose at most 20 CSV files.")
                        for (i in 0 until clips.itemCount) uris.add(clips.getItemAt(i).uri)
                    } else data?.data?.let { uris.add(it) }
                    response = uris.map { uri ->
                        val name = fileName(uri)
                        if (!dataSelection && !name.endsWith(".csv", ignoreCase = true)) throw IllegalStateException("Choose CSV files only.")
                        val stream = contentResolver.openInputStream(uri) ?: throw IllegalStateException("Could not read $name.")
                        val bytes = ByteArrayOutputStream()
                        stream.use {
                            val buffer = ByteArray(8192)
                            var count = it.read(buffer)
                            while (count != -1) {
                                if (bytes.size() + count > 4 * 1024 * 1024) throw IllegalStateException("Each CSV must be 4 MB or smaller.")
                                bytes.write(buffer, 0, count)
                                count = it.read(buffer)
                            }
                        }
                        mapOf("name" to name, "bytes" to bytes.toByteArray())
                    }
                }
                runOnUiThread {
                    if (pending === result) {
                        pending = null
                        templateText = null
        exportPath = null
                        result.success(response)
                    }
                }
            } catch (e: Exception) {
                runOnUiThread {
                    if (pending === result) finishError("file_io", e.message ?: "Could not process the selected file.")
                }
            }
        }
    }
    override fun onDestroy() {
        externalFiles?.close()
        studioPdfEngine?.close()
        documentScanner?.close()
        cameraCapture?.close()
        liveScanner?.close()
        pending?.error("interrupted", "File selection was interrupted. Please retry.", null)
        pending = null
        fileWorker.shutdown()
        super.onDestroy()
    }
    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        externalFiles?.receive(intent)
    }
}

