import 'dart:io';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hive_flutter/hive_flutter.dart';
import 'package:go_router/go_router.dart';
import 'package:hyzen_pharmd/features/pdf_studio/data/studio_storage.dart';
import 'package:hyzen_pharmd/features/pdf_studio/data/pdf_studio_repository.dart';
import 'package:hyzen_pharmd/core/storage/local_store.dart';
import 'package:hyzen_pharmd/features/pdf_studio/data/studio_pdf_engine.dart';
import 'package:hyzen_pharmd/features/pdf_studio/presentation/scan_pdf_screen.dart';
import 'package:hyzen_pharmd/features/pdf_studio/presentation/rich_document_screen.dart';

class _ScanStorage implements StudioStorage {
  @override
  Future<StoredStudioFile> importCopy(String sourcePath, String id) async =>
      StoredStudioFile(
        path: '/private/$id.pdf',
        editStatePath: '/private/${id}_state.json',
        sizeBytes: 1234,
        extension: 'pdf',
      );
  @override
  Future<bool> exists(String path) async => true;
  @override
  Future<void> deleteStored({
    required String path,
    required String editStatePath,
  }) async {}
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  const camera = MethodChannel('com.hyzen.pharmd/camera_pages');
  const live = MethodChannel('com.hyzen.pharmd/live_scanner');
  const pdf = MethodChannel('com.hyzen.pharmd/pdf_studio');
  final messenger =
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger;
  late Directory directory;
  setUp(() async {
    messenger.setMockMethodCallHandler(
      const MethodChannel('com.hyzen.pharmd/document_scanner'),
      (_) async => await camera.invokeListMethod<String>('capture'),
    );
    directory = await Directory.systemTemp.createTemp('hyzen-scan-test-');
    Hive.init(directory.path);
    await Hive.openBox<String>(Boxes.pdfStudioHistory);
  });
  tearDown(() async {
    messenger.setMockMethodCallHandler(
      const MethodChannel('com.hyzen.pharmd/document_scanner'),
      null,
    );
    messenger.setMockMethodCallHandler(live, null);
    messenger.setMockMethodCallHandler(camera, null);
    messenger.setMockMethodCallHandler(pdf, null);
    await Hive.close();
    await directory.delete(recursive: true);
  });
  testWidgets('page history uses the latest native path after undo and reset', (tester) async {
    tester.view.physicalSize = const Size(320, 900);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final calls = <MethodCall>[];
    var path = '/tmp/edited.jpg';
    messenger.setMockMethodCallHandler(camera, (call) async {
      calls.add(call);
      if (call.method == 'undo') path = '/tmp/undone.jpg';
      if (call.method == 'reset') path = '/tmp/reset.jpg';
      return [path];
    });
    await tester.pumpWidget(const ProviderScope(child: MaterialApp(home: ScanPdfScreen())));
    await tester.pumpAndSettle();
    await tester.tap(find.byTooltip('Page 1 history'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Undo last edit'));
    await tester.pumpAndSettle();
    expect(calls.singleWhere((c) => c.method == 'undo').arguments['path'], '/tmp/edited.jpg');
    await tester.tap(find.byTooltip('Page 1 history'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Reset to imported image'));
    await tester.pumpAndSettle();
    expect(calls.singleWhere((c) => c.method == 'reset').arguments['path'], '/tmp/undone.jpg');
    expect(find.text('Page 1'), findsOneWidget);
    expect(tester.takeException(), isNull);
  }, variant: TargetPlatformVariant.only(TargetPlatform.android));
  testWidgets('custom live camera returns captured pages directly to review', (tester) async {
    messenger.setMockMethodCallHandler(camera, (_) async => <String>[]);
    messenger.setMockMethodCallHandler(live, (call) async => {'pages': ['/tmp/live-one.jpg', '/tmp/live-two.jpg'], 'action': 'review'});
    var legacyOpened = false;
    messenger.setMockMethodCallHandler(const MethodChannel('com.hyzen.pharmd/document_scanner'), (_) async { legacyOpened = true; return <String>[]; });
    await tester.pumpWidget(const ProviderScope(child: MaterialApp(home: ScanPdfScreen())));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Scan'));
    await tester.pumpAndSettle();
    expect(find.text('Page 2'), findsOneWidget);
    expect(legacyOpened, isFalse);
  }, variant: TargetPlatformVariant.only(TargetPlatform.android));
  testWidgets('other scanner is opened only when explicitly selected in live camera', (tester) async {
    messenger.setMockMethodCallHandler(camera, (_) async => <String>[]);
    messenger.setMockMethodCallHandler(live, (_) async => {'pages': <String>[], 'action': 'legacy'});
    var legacyOpened = false;
    messenger.setMockMethodCallHandler(const MethodChannel('com.hyzen.pharmd/document_scanner'), (_) async { legacyOpened = true; return ['/tmp/legacy.jpg']; });
    await tester.pumpWidget(const ProviderScope(child: MaterialApp(home: ScanPdfScreen())));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Scan'));
    await tester.pumpAndSettle();
    expect(legacyOpened, isTrue);
    expect(find.text('Page 1'), findsOneWidget);
  }, variant: TargetPlatformVariant.only(TargetPlatform.android));
  testWidgets('selected pages are removed together and restored in one action', (tester) async {
    var pages = ['/tmp/one.jpg', '/tmp/two.jpg'];
    final calls = <MethodCall>[];
    messenger.setMockMethodCallHandler(camera, (call) async {
      calls.add(call);
      if (call.method == 'replace') pages = List<String>.from(call.arguments['paths']);
      if (call.method == 'undoRemoval') pages = ['/tmp/one.jpg', '/tmp/two.jpg'];
      return pages;
    });
    await tester.pumpWidget(const ProviderScope(child: MaterialApp(home: ScanPdfScreen())));
    await tester.pumpAndSettle();
    await tester.tap(find.byTooltip('Discard current scan'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Keep scan'));
    await tester.pumpAndSettle();
    expect(calls.where((c) => c.method == 'clear'), isEmpty);
    await tester.tap(find.text('Select pages'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Select all'));
    await tester.pump();
    await tester.tap(find.text('Remove 2'));
    await tester.pumpAndSettle();
    expect(calls.singleWhere((c) => c.method == 'replace').arguments['paths'], isEmpty);
    expect(find.text('Add your first page'), findsOneWidget);
    await tester.tap(find.byTooltip('Restore last removed pages'));
    await tester.pumpAndSettle();
    expect(find.text('Page 2'), findsOneWidget);
    expect(tester.takeException(), isNull);
  }, variant: TargetPlatformVariant.only(TargetPlatform.android));
  testWidgets('saved scan restores through the archive channel', (tester) async {
    final calls = <MethodCall>[];
    messenger.setMockMethodCallHandler(camera, (call) async { calls.add(call); return ['/tmp/restored.jpg']; });
    await tester.pumpWidget(const ProviderScope(child: MaterialApp(home: ScanPdfScreen(archiveId: 'saved_scan_1'))));
    await tester.pumpAndSettle();
    expect(calls.first.method, 'openArchive');
    expect(calls.first.arguments['id'], 'saved_scan_1');
    expect(find.text('Page 1'), findsOneWidget);
  }, variant: TargetPlatformVariant.only(TargetPlatform.android));
  testWidgets(
    'native multi-page scanner returns to a usable page grid',
    (tester) async {
      var scanned = false;
      messenger.setMockMethodCallHandler(camera, (_) async => <String>[]);
      messenger.setMockMethodCallHandler(
        const MethodChannel('com.hyzen.pharmd/document_scanner'),
        (call) async {
          scanned = call.method == 'scan';
          return ['/tmp/scanned-one.jpg', '/tmp/scanned-two.jpg'];
        },
      );
      await tester.pumpWidget(
        const ProviderScope(child: MaterialApp(home: ScanPdfScreen())),
      );
      await tester.pumpAndSettle();
      await tester.tap(find.text('Scan'));
      await tester.pumpAndSettle();
      expect(scanned, isTrue);
      expect(find.text('2 pages'), findsOneWidget);
      expect(find.byTooltip('Crop / filter page 1'), findsOneWidget);
      expect(find.byTooltip('Rotate page 2'), findsOneWidget);
      expect(tester.takeException(), isNull);
    },
    variant: TargetPlatformVariant.only(TargetPlatform.android),
  );
  testWidgets(
    'cancelled capture leaves an empty draft and disabled save',
    (tester) async {
      messenger.setMockMethodCallHandler(camera, (_) async => <String>[]);
      await tester.pumpWidget(
        const ProviderScope(child: MaterialApp(home: ScanPdfScreen())),
      );
      await tester.pumpAndSettle();
      await tester.tap(find.text('Scan'));
      await tester.pumpAndSettle();
      expect(find.text('Add your first page'), findsOneWidget);
      expect(
        tester
            .widget<FilledButton>(
              find.byWidgetPredicate((w) => w is FilledButton),
            )
            .onPressed,
        isNull,
      );
      expect(Hive.box<String>(Boxes.pdfStudioHistory).isEmpty, isTrue);
    },
    variant: TargetPlatformVariant.only(TargetPlatform.android),
  );
  testWidgets(
    'each confirmed camera capture appends another page',
    (tester) async {
      final pages = <String>[];
      messenger.setMockMethodCallHandler(camera, (call) async {
        if (call.method == 'capture') pages.add('/tmp/page${pages.length}.jpg');
        return [...pages];
      });
      await tester.pumpWidget(
        const ProviderScope(child: MaterialApp(home: ScanPdfScreen())),
      );
      await tester.pumpAndSettle();
      await tester.tap(find.text('Scan'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Scan'));
      await tester.pumpAndSettle();
      expect(find.text('Page 1'), findsOneWidget);
      expect(find.text('Page 2'), findsOneWidget);
      expect(find.byTooltip('Remove page 1'), findsOneWidget);
      expect(tester.takeException(), isNull);
    },
    variant: TargetPlatformVariant.only(TargetPlatform.android),
  );
  testWidgets(
    'restored camera draft survives a recreated Flutter screen',
    (tester) async {
      messenger.setMockMethodCallHandler(
        camera,
        (_) async => ['/tmp/one.jpg', '/tmp/two.jpg'],
      );
      await tester.pumpWidget(
        const ProviderScope(child: MaterialApp(home: ScanPdfScreen())),
      );
      await tester.pumpAndSettle();
      expect(find.text('2 pages'), findsOneWidget);
      await tester.pumpWidget(const SizedBox.shrink());
      await tester.pumpWidget(
        const ProviderScope(child: MaterialApp(home: ScanPdfScreen())),
      );
      await tester.pumpAndSettle();
      expect(find.text('Page 2'), findsOneWidget);
      expect(tester.takeException(), isNull);
    },
    variant: TargetPlatformVariant.only(TargetPlatform.android),
  );
  testWidgets(
    'camera error preserves gallery action and existing pages',
    (tester) async {
      messenger.setMockMethodCallHandler(camera, (call) async {
        if (call.method == 'capture') {
          throw PlatformException(
            code: 'camera',
            message: 'Choose gallery images instead.',
          );
        }
        return ['/tmp/one.jpg'];
      });
      await tester.pumpWidget(
        const ProviderScope(child: MaterialApp(home: ScanPdfScreen())),
      );
      await tester.pumpAndSettle();
      await tester.tap(find.text('Scan'));
      await tester.pumpAndSettle();
      expect(find.text('Choose gallery images instead.'), findsOneWidget);
      expect(find.byTooltip('Choose gallery images'), findsOneWidget);
      expect(find.text('Page 1'), findsOneWidget);
      expect(tester.takeException(), isNull);
    },
    variant: TargetPlatformVariant.only(TargetPlatform.android),
  );
